// Purchase Type indicates what kind of purchase a discovery result represents.
// Returned by [Search](/api/v1/reference/domains/search) and [Check Availability](/api/v1/reference/domains/check-availability) — not [Zone Check](/api/v1/reference/domains/zone-check).
//
// Copy the value to [Create Domain](/api/v1/reference/domains/create-domain) as `purchaseType`.
//
// **Recommendation:** Pass `registration` on Search and Check Availability unless you choose to support acquisition inventory. Other values are supported but add integration complexity.
//
// **Pricing by type:**
//
// - `registration` — Standard or registry premium. Check the `premium` flag: when `false`, omit `purchasePrice` on create (Get Pricing with matching `years` is optional for preview only); when `true`, `purchasePrice` is required from Get Pricing with matching `years`. `years` controls price and registration length.
// - `aftermarket_s`, `aftermarket_b`, `aftermarket_i` — Flat acquisition fee from Search or Check Availability; `purchasePrice` required. `years` does not multiply price or guarantee registration length — omit or pass TLD default.
// - `expiring`, `backorder` — Flat acquisition fee from Search or Check Availability; `purchasePrice` required. Get Pricing does not return these prices. `years` does not multiply price or guarantee registration length — omit or pass TLD default. Renew after acquisition to extend registration.
//
// See the [Domain pricing guide](/guides/domain-pricing).
type SearchPurchaseType string

const (
	SearchPurchaseTypeRegistration SearchPurchaseType = "registration"
	SearchPurchaseTypeAftermarketI SearchPurchaseType = "aftermarket_i"
	SearchPurchaseTypeExpiring     SearchPurchaseType = "expiring"
	SearchPurchaseTypeBackorder    SearchPurchaseType = "backorder"
	SearchPurchaseTypeAftermarketS SearchPurchaseType = "aftermarket_s"
	SearchPurchaseTypeAftermarketB SearchPurchaseType = "aftermarket_b"
)

func NewSearchPurchaseTypeFromString(s string) (SearchPurchaseType, error) {
	switch s {
	case "registration":
		return SearchPurchaseTypeRegistration, nil
	case "aftermarket_i":
		return SearchPurchaseTypeAftermarketI, nil
	case "expiring":
		return SearchPurchaseTypeExpiring, nil
	case "backorder":
		return SearchPurchaseTypeBackorder, nil
	case "aftermarket_s":
		return SearchPurchaseTypeAftermarketS, nil
	case "aftermarket_b":
		return SearchPurchaseTypeAftermarketB, nil
	}
	var t SearchPurchaseType
	return "", fmt.Errorf("%s is not a valid %T", s, t)
}

func (s SearchPurchaseType) Ptr() *SearchPurchaseType {
	return &s
}

